import{_ as i,l,o as e,c as n,v as o,p as h,x as r,d as s,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"高阶场内校正","description":"","frontmatter":{"title":"高阶场内校正","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/high-order-field-correction.md","filePath":"litho/high-order-field-correction.md","lastUpdated":1789023840000}'),c={name:"litho/high-order-field-correction.md"};function E(_,a,A,B,f,m){const t=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="高阶场内校正" tabindex="-1">高阶场内校正 <a class="header-anchor" href="#高阶场内校正" aria-label="Permalink to &quot;高阶场内校正&quot;">​</a></h1><div class="epigraph"><p>线性项吃掉场的刚体；弓形、扫描偏扭和工艺弯月要靠场内高阶项，而项数不得超过抽样能辨识的自由度。</p><footer>—— 对照 ASML 对高阶 overlay 校正的公开论述；[高阶套刻](/litho/high-order-overlay) 已钉来源</footer></div><p><a href="/litho/overlay-control-loop">上一课</a>给出套刻环。缺口是开哪些场内项：<a href="/litho/high-order-overlay">高阶套刻</a> 已列镜头、扫描与翘曲来源；本课钉<strong>控制政策</strong>：默认开几阶、何时升级、如何防止噪声拟合。批次分派与重工，留给[下一课](/litho/lot-disposition-rework）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>场内校正项一多，残差图变花就是过拟合：边场点少、噪声当弓形，下一场补反。项太少，工艺弯月留在器件上，规格只在场心满足。政策应是：稳态用经能力验证的项集；事件（换胶、新 PECVD 应力、新掩模书写指纹）后加密抽样，再决定是否升级项。</p><p>缺口是<strong>可辨识性</strong>，不是再列 Zernike 式的套刻多项式。扫描机提供的校正器有物理限幅；模型项还要映射到可执行的台/镜头调节，否则只是计量拟合，曝光时做不到。</p><h3 id="场间与场内不要抢账" tabindex="-1">场间与场内不要抢账 <a class="header-anchor" href="#场间与场内不要抢账" aria-label="Permalink to &quot;场间与场内不要抢账&quot;">​</a></h3><p>晶圆径向膨胀主要是场间；镜头畸变是场内。把径向全塞进场内高阶，产品换场排布就崩。 holistic 校正把晶圆、场、扫描方向分开，政策应保持这本账。</p><p><span class="marginnote">新掩模的书写指纹是「场内且稳定」的，可用掩模专用校正，不必每片重估。把它当随机高阶，会污染机台指纹。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>项集版本与抽样计划同发。验证：保持场加密计量，看预测残差是否下降、是否在新产品上泛化。映射：项 → 扫描机调节器行程，检查饱和。与 CD：某些调节器（镜头加热补偿）同时动 CD， holistic 要联合，本课只要求套刻项不要偷偷拧照明。</p><p>新产品导入用加密计量跑两周，再决定稳态项集。把导入期的高阶项直接冻进量产，会把首批噪声变成永久指纹。ASML 公开论述强调校正与采样匹配，本课把匹配写成政策版本号。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小二乘拟合高阶项，设计矩阵由测点坐标决定。点布局差则条件数爆。正则化或固定不显著项，等于降低有效阶次。控制上，用上一批系数的 EWMA，而不是本片噪声系数直接曝光——除非本片对准点数已经支撑该阶（少见）。</p>',14)),(e(),h(p,null,{default:r(()=>[d(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAMP%5B%22%E5%9C%BA%E5%86%85%E7%82%B9%E6%95%B0%22%5D%20--%3E%20DOF%5B%22%E5%8F%AF%E5%BC%80%E9%98%B6%E6%AC%A1%22%5D%0A%20%20SRC%5B%22%E9%95%9C%E5%A4%B4%20%2F%20%E6%89%AB%E6%8F%8F%20%2F%20%E7%BF%98%E6%9B%B2%22%5D%20--%3E%20TERM%5B%22%E5%80%99%E9%80%89%E9%A1%B9%22%5D%0A%20%20DOF%20--%3E%20POL%5B%22%E6%94%BF%E7%AD%96%E9%A1%B9%E9%9B%86%22%5D%0A%20%20TERM%20--%3E%20POL%0A%20%20POL%20--%3E%20MAP%5B%22%E8%B0%83%E8%8A%82%E5%99%A8%E6%98%A0%E5%B0%84%20%2B%20%E9%99%90%E5%B9%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>项数受点数与调节器行程双重约束。过拟合的残差图变花；政策失败的标志是新产品上泛化变差。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重复高阶来源的全文。不编造某 Twinscan 的项名称表。High-NA 半场拼接有自己的场内不连续，不在本课用光滑多项式假装。</p><p>后课默认：项集与抽样绑定，过拟合即政策失败。下一课：残差仍超规格时如何分派与重工。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>场内高阶项数受抽样自由度与调节器行程约束。</li><li>稳态项集与事件升级要分开。</li><li>掩模指纹与机台指纹分账。</li><li>出处：ASML 高阶 overlay 校正公开论述；前课来源不重写。</li></ul>',6))])}const T=i(c,[["render",E]]);export{P as __pageData,T as default};
